import { useSelector } from 'react-redux'

import Tarefa from '../../components/Tarefa'
import { Container } from './styles'
import { RootReducer } from '../../store'
import userEvent from '@testing-library/user-event'

const ListaDeTarefas = () => {
  const { itens } = useSelector((state: RootReducer) => state.tarefas)
  const { termo, criterio, valor } = useSelector(
    (state: RootReducer) => state.filtro
  )

  const filtraTarefas = () => {
    let tarefasFiltradas = itens
    if (termo !== undefined) {
      tarefasFiltradas = tarefasFiltradas.filter(
        (item) => item.titulo.toLowerCase().search(termo.toLowerCase()) >= 0
      )

      if (criterio === 'prioridade') {
        tarefasFiltradas = tarefasFiltradas.filter(
          (item) => item.prioridade === valor
        )
      } else if (criterio === 'status') {
        tarefasFiltradas = tarefasFiltradas.filter(
          (item) => item.status === valor
        )
      }
      return tarefasFiltradas
    } else {
      return itens
    }
  }

  const exibeResultadoFiltrage = (quantidade: number) => {
    let mensagem = ''
    const complementacao =
      termo !== undefined && termo.length > 0 ? `e "${termo}";` : ''

    if (criterio === 'todas') {
      mensagem = `${quantidade} tarefas encontradas como: todas ${complementacao}`
    } else {
      mensagem = `${quantidade} tarefas encontradas como: "${`${criterio}=${valor}`} ${
        termo !== undefined && termo.length > 0 ? `e "${termo}";` : ''
      }"`
    }
  }
  const tarefas = filtraTarefas()

  return (
    <Container>
      <p>
        {tarefas.length} tarefas marcadas como: &quot;{`${criterio}=${valor}`}
        &ldquo; {termo !== undefined && termo.length > 0 ? `e "${termo}";` : ''}
      </p>
      <ul>
        <li>{termo}</li>
        <li>{criterio}</li>
        <li>{valor}</li>
      </ul>
      <ul>
        {tarefas.map((t) => (
          <li key={t.titulo}>
            <Tarefa
              id={t.id}
              descricao={t.descricao}
              titulo={t.titulo}
              status={t.status}
              prioridade={t.prioridade}
            />
          </li>
        ))}
      </ul>
    </Container>
  )
}

export default ListaDeTarefas
function filtraTarefas() {
  throw new Error('Function not implemented.')
}
